package fr.cercle.aplomb;
import android.app.Activity;import android.os.Bundle;import android.view.*;import android.graphics.*;import android.content.*;import java.util.*;
public class MainActivity extends Activity{
 Game game; public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);game=new Game(this);setContentView(game);} public void onPause(){super.onPause();game.paused=true;} public void onResume(){super.onResume();if(game!=null)game.last=0;}
 class Game extends View{
 final int mode=1; Paint p=new Paint(3); Random random=new Random(); float scale,ox,oy; long last; boolean ready=false,paused=false,over=false,drag=false,flying=false,narrow=false; int score=0,turn=0,best=0,bounces=0,round=0; float px,py,vx,vy,aimx,aimy,clock,zone,fall=0,blockX=360,blockW; String message=""; ArrayList<float[]> targets=new ArrayList<>(),blocks=new ArrayList<>();
 int ink=Color.rgb(13,23,29),panel=Color.rgb(25,42,49),paper=Color.rgb(237,232,215),muted=Color.rgb(155,178,181),gold=Color.rgb(132,194,164); 
 Game(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);best=getPreferences(0).getInt("best",0);reset();setContentDescription("Aplomb : jeu tactile hors ligne");}
 void reset(){round++; score=turn=bounces=0;fall=0;over=drag=flying=false;message="";targets.clear();blocks.clear();if(mode==0){for(int y=0;y<3;y++)for(int x=0;x<4;x++)targets.add(new float[]{135+x*150+(y%2)*12,390+y*130,1+y});px=360;py=990;}if(mode==1){blocks.add(new float[]{360,1010,330,55});piece();}if(mode==2)nextBrake();last=0;invalidate();}
 void piece(){blockW=150+random.nextInt(100);blockX=360;}
 void nextBrake(){px=80;py=620;vx=300+turn*28;flying=false;ready=true;drag=false;clock=0;zone=435+random.nextInt(105);message="Choisis ta zone, puis touche FREINER.";}
 void finish(){over=true;flying=false;message="";if(score>best){best=score;getPreferences(0).edit().putInt("best",best).apply();}}
 void color(int c){p.setColor(c);p.setStyle(Paint.Style.FILL);} void text(Canvas c,String s,float x,float y,int sz,int col){color(col);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(sz);c.drawText(s,x,y,p);} void rect(Canvas c,float x,float y,float w,float h,int col){color(col);c.drawRoundRect(x,y,x+w,y+h,18,18,p);} void line(Canvas c,float x,float y,float a,float b,int col,int width){color(col);p.setStrokeWidth(width);c.drawLine(x,y,a,b,p);} void dot(Canvas c,float x,float y,float r,int col){color(col);c.drawCircle(x,y,r,p);} void button(Canvas c,String s,float x,float y,float w,int col){rect(c,x,y,w,86,col);text(c,s,x+20,y+53,24,col==gold?ink:paper);}
 protected void onDraw(Canvas c){super.onDraw(c);long now=System.nanoTime();float dt=last==0?0:Math.min(.035f,(now-last)/1e9f);last=now;if(!paused&&!over)step(dt);scale=Math.min(getWidth()/720f,getHeight()/1280f);ox=(getWidth()-720*scale)/2;oy=(getHeight()-1280*scale)/2;c.drawColor(ink);c.save();c.translate(ox,oy);c.scale(scale,scale);
 text(c,"LES PETITS JEUX / PROTOTYPE 0.1",30,52,18,muted);text(c,"Aplomb",30,112,49,paper);button(c,paused?"REPRENDRE":"PAUSE",500,65,190,panel);text(c,"SCORE  "+score,30,175,26,gold);text(c,"RECORD  "+best,390,175,22,muted);
 rect(c,30,210,660,845,panel);
 if(mode==0){text(c,"TIR "+Math.min(3,turn+1)+" / 3",58,252,22,muted);text(c,"3 tirs. Rebond = multiplicateur.",58,290,23,paper);for(float[] t:targets){dot(c,t[0],t[1],34,gold);text(c,""+(int)t[2],t[0]-8,t[1]+9,26,ink);}dot(c,px,py,15,paper);if(drag){float dx=aimx-px,dy=aimy-py,len=(float)Math.hypot(dx,dy);if(len>10){line(c,px,py,px+dx/len*150,py+dy/len*150,gold,4);}} text(c,"REBONDS "+bounces,58,1030,20,muted);}
 if(mode==1){text(c,"PIÈCE "+Math.min(8,turn+1)+" / 8",58,252,22,muted);text(c,"Déborde pour marquer, garde l’équilibre.",58,292,22,paper);for(int i=0;i<blocks.size();i++){float[] b=blocks.get(i);rect(c,b[0]-b[2]/2,b[1]-b[3]/2,b[2],b[3],i==0?muted:gold);}if(!over){rect(c,blockX-blockW/2,365,blockW,55,gold);line(c,blockX,425,blockX,950-turn*55,muted,2);}text(c,"La ligne indique le centre de ta pièce.",58,330,19,muted);}
 if(mode==2){text(c,"ESSAI "+Math.min(5,turn+1)+" / 5",58,252,22,muted);text(c,"Un freinage. L’inertie fait le reste.",58,292,23,paper);float half=narrow?29:75;rect(c,zone-half,475,half*2,285,gold);text(c,narrow?"× 3":"× 1",zone-22,450,24,gold);line(c,65,620,655,620,muted,5);dot(c,px,620,24,paper);text(c,"VITESSE  "+(int)Math.abs(vx),58,850,22,muted);button(c,"LARGE",65,915,270,!narrow?gold:ink);button(c,"PRÉCISE ×3",350,915,300,narrow?gold:ink);}
 text(c,message.length()>53?message.substring(0,53):message,35,1101,22,gold);
 if(!over){String hint=mode==0?(flying?"La bille joue…":"Glisse depuis la bille vers ta cible."):mode==1?"Glisse la pièce, puis relâche pour la poser.":drag?(flying?"Freinage en cours…":"Touche CONTINUER."):ready?"Choisis ta zone, puis lance le palet.":"Touche FREINER au bon moment.";text(c,hint,35,1146,22,paper);if(mode==2)button(c,flying?(drag?"FREINAGE…":"FREINER"):(ready?"LANCER":"CONTINUER"),30,1170,660,gold);else button(c,"RECOMMENCER",30,1170,660,ink);}
 if(over){rect(c,55,450,610,415,ink);text(c,"PARTIE TERMINÉE",90,520,32,paper);text(c,""+score+" points",90,600,58,gold);text(c,"Une nouvelle partie, un meilleur geste.",90,658,23,muted);button(c,"REJOUER",90,705,540,gold);}
 if(paused){rect(c,55,430,610,330,ink);text(c,"PAUSE",100,510,40,gold);text(c,"La partie attend ton retour.",100,570,26,paper);button(c,"REPRENDRE",100,620,520,panel);}c.restore();if(!paused&&!over)postInvalidateDelayed(16);}
 void step(float dt){if(mode==0&&flying){int steps=5;for(int i=0;i<steps;i++){px+=vx*dt/steps;py+=vy*dt/steps;if(px<60){px=120-px;vx=Math.abs(vx);bounces++;}if(px>660){px=1320-px;vx=-Math.abs(vx);bounces++;}if(py<325){py=650-py;vy=Math.abs(vy);bounces++;}for(int n=targets.size()-1;n>=0;n--){float[] t=targets.get(n);if(Math.hypot(px-t[0],py-t[1])<46){score+=(int)t[2]*10*(1+Math.min(3,bounces));targets.remove(n);}}}clock+=dt;if(py>1015||clock>5.5||targets.isEmpty()){flying=false;turn++;if(turn>=3||targets.isEmpty())finish();else{px=360;py=990;message="Prépare le prochain angle.";}}}if(mode==2&&flying){px+=vx*dt;if(drag){vx=Mechanics.brake(vx,dt,300);if(vx==0){flying=false;float distance=Math.abs(px-zone),half=narrow?29:75;if(distance<=half){int points=Math.round(100*(1-distance/half))*(narrow?3:1);score+=points;message="Dans la zone : +"+points+" points.";}else message="À côté. Un peu plus tôt ou plus tard.";}}if(px>665){px=665;vx=0;flying=false;message="Trop loin ! Anticipe le freinage.";}}}
 void drop(){float[] top=blocks.get(blocks.size()-1);float lo=Math.max(blockX-blockW/2,top[0]-top[2]/2),hi=Math.min(blockX+blockW/2,top[0]+top[2]/2);if(hi-lo<15){finish();return;}blocks.add(new float[]{blockX,955-turn*55,blockW,48});if(!Mechanics.stable(blocks)){blocks.remove(blocks.size()-1);finish();return;}score+=20+Math.round(Math.abs(blockX-top[0])/3);turn++;if(turn>=8)finish();else{piece();message="Stable ! Prépare la pièce suivante.";}}
 public boolean onTouchEvent(android.view.MotionEvent e){float x=(e.getX()-ox)/scale,y=(e.getY()-oy)/scale;int a=e.getActionMasked();if(a==android.view.MotionEvent.ACTION_CANCEL){drag=false;return true;}if(a==0){if(paused){paused=false;last=0;invalidate();return true;}if(x>490&&y<160){paused=true;invalidate();return true;}if(over){if(y>700&&y<810)reset();return true;}if(mode==0&&!flying&&y>320&&y<1100){drag=true;aimx=x;aimy=y;}if(mode==1&&y>320&&y<1100){drag=true;blockX=Math.max(60+blockW/2,Math.min(660-blockW/2,x));}if(mode==2){if(y>900&&y<1005&&!drag){narrow=x>345;}else if(y>1160){if(!flying){if(ready){ready=false;flying=true;}else{turn++;if(turn>=5)finish();else nextBrake();}}else drag=true;}}if(mode!=2&&y>1170)reset();invalidate();return true;}if(a==2&&drag){aimx=x;aimy=y;if(mode==1)blockX=Math.max(60+blockW/2,Math.min(660-blockW/2,x));invalidate();}if(a==1&&drag&&mode<2){drag=false;if(mode==1)drop();else{float dx=x-px,dy=Math.min(-70,y-py),len=(float)Math.hypot(dx,dy);if(len>30){vx=dx/len*850;vy=dy/len*850;flying=true;clock=0;bounces=0;message="";}}invalidate();}return true;}
 }
}
